    for i in range(n):
        for j in range(i+1, n):
            if nums[i] + nums[j] == target:
                return [i, j]
    return [-1, -1]

def two_sum(nums, target):
    index = {}
    for i, x in enumerate(nums):
        c = target - x
        if c in index:
            return [index[c], i]
        index[x] = i
    return [-1, -1]

def two_sum_sorted(nums, target):
    arr = sorted((x, i) for i, x in enumerate(nums))
    l, r = 0, len(arr) - 1
    while l < r:
        s = arr[l][0] + arr[r][0]
        if s == target:
            return [arr[l][1], arr[r][1]]
        if s < target:
            l += 1
        else:
            r -= 1
    return [-1, -1]
